use anyhow :: { Context , Result } ; use std :: path :: Path ; use std :: process :: Command ; use std :: sync :: { Arc , Mutex } ; fn get_git_commit_hash (repo_path : & Path) -> Result < String > { let output = Command :: new ("git") . arg ("rev-parse") . arg ("HEAD") . current_dir (repo_path) . output () . context ("Failed to get git commit hash") ? ; if output . status . success () { let hash = String :: from_utf8_lossy (& output . stdout) . trim () . to_string () ; Ok (hash) } else { anyhow :: bail ! ("Failed to get commit hash: {}" , String :: from_utf8_lossy (& output . stderr)) } }